// Render @tropel/shims dist/bundle.js + dist/bundle.d.ts from the shim/
// sources copied by build.sh. The default order and the render() separator
// are the PARITY CONTRACT: byte-identical to the engine's ShimBundle
// (crates/tropel-engine/src/js_bootstrap.rs — ShimBundle::default() and
// ShimBundle::render()).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");

// ── the engine's ShimBundle::default() order (do not reorder) ────────────
// SINGLE AUTHORITY: crates/tropel-engine/src/js_bootstrap.rs
// (ShimBundle::default()). If that file gains or reorders an entry, update
// this list AND smoke.mjs's DEFAULT_ORDER together — the smoke proves
// content parity, not list completeness.
const DEFAULT_ORDER = [
  ["deep-equal-shim", "shim/deep-equal.js"],
  ["k6-core-shim", "shim/k6-core.js"],
  ["pm-shim", "shim/pm.js"],
  ["chai-shim", "shim/chai-shim.js"],
  ["lodash-shim", "shim/lodash-shim.js"],
  ["cryptojs-shim", "shim/cryptojs.js"],
  ["exec-shim", "shim/exec.js"],
  ["bru-shim", "shim/bru.js"],
];

// The k6 family — used by the k6 input driver, not part of the PM default
// bundle, but shipped for embedders who run k6-style scripts.
const K6_ORDER = [
  ["k6-shim", "shim/k6-shim.js"],
  ["jslib-shim", "shim/jslib-shim.js"],
  ["open-data-shim", "shim/open-data-shim.js"],
  ["sleep-shim", "shim/sleep-shim.js"],
];

const read = (rel) => readFileSync(join(root, rel), "utf8");

const defaultBundle = DEFAULT_ORDER.map(([name, rel]) => ({
  name,
  source: read(rel),
}));
const k6Bundle = K6_ORDER.map(([name, rel]) => ({
  name,
  source: read(rel),
}));

// ShimBundle::render(): "// ==== shim: {name} ====\n" + src + "\n"
const renderFn = (entries) =>
  entries
    .map(({ name, source }) => `// ==== shim: ${name} ====\n${source}\n`)
    .join("");

const json = (v) => JSON.stringify(v, null, 2);

const bundleJs = `// Generated by scripts/render-bundle.mjs — do not edit.
// The default bundle mirrors the engine's ShimBundle::default() exactly
// (crates/tropel-engine/src/js_bootstrap.rs); render() mirrors render().

export const defaultBundle = ${json(defaultBundle)};

export const k6Bundle = ${json(k6Bundle)};

/** Concatenate shim entries with the engine's \`// ==== shim: {name} ====\\n\` separators. */
export function render(entries = defaultBundle) {
  return entries
    .map(({ name, source }) => \`// ==== shim: \${name} ====\\n\${source}\\n\`)
    .join("");
}
`;

const bundleDts = `// Generated by scripts/render-bundle.mjs — do not edit.
export interface ShimEntry {
  name: string;
  source: string;
}

/** The engine's ShimBundle::default() — pm, chai, lodash, cryptojs, exec, bru, in order. */
export declare const defaultBundle: ShimEntry[];
/** The k6 input-driver family: k6-shim, open-data-shim, sleep-shim. */
export declare const k6Bundle: ShimEntry[];
/** Concatenate shim entries with the engine's \`// ==== shim: {name} ====\\n\` separators. */
export declare function render(entries?: ShimEntry[]): string;
`;

mkdirSync(join(root, "dist"), { recursive: true });
writeFileSync(join(root, "dist", "bundle.js"), bundleJs);
writeFileSync(join(root, "dist", "bundle.d.ts"), bundleDts);

const total = [...defaultBundle, ...k6Bundle].reduce(
  (n, e) => n + e.source.length,
  0
);
console.log(
  `  rendered dist/bundle.js + bundle.d.ts (${defaultBundle.length} default + ${k6Bundle.length} k6 shims, ${total} bytes)`
);
